from gurobipy import Model, GRB, quicksum
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
shelf_ids = [int(r['values']['ShelfID']) for r in capacity_records]
product_names = [int(r['values']['ProductName']) for r in product_records]
capacities = {}
for r in capacity_records:
    sid = int(r['values']['ShelfID'])
    cap = int(r['values']['Capacity'])
    capacities[sid] = cap
values = {}
weights = {}
for r in product_records:
    pid = int(r['values']['ProductName'])
    val = int(r['values']['Value'])
    wgt = int(r['values']['Weight'])
    values[pid] = val
    weights[pid] = wgt
if set(shelf_ids) != set(range(1, 11)):
    raise ValueError('ShelfIDs missing or out of range 1-10')
if set(product_names) != set(range(1, 21)):
    raise ValueError('ProductNames missing or out of range 1-20')
if any((sid not in capacities for sid in shelf_ids)):
    raise ValueError('Missing capacity for some shelf')
if any((pid not in values or pid not in weights for pid in product_names)):
    raise ValueError('Missing value or weight for some product')

def build_model():
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(shelf_ids, product_names, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((values[j] * x_vars[i, j] for i in shelf_ids for j in product_names)), GRB.MAXIMIZE)
    for i in shelf_ids:
        m.addConstr(quicksum((weights[j] * x_vars[i, j] for j in product_names)) <= capacities[i], name='cap_%d' % i)
    return m
m = build_model()
m.optimize()
if m.Status == GRB.OPTIMAL:
    print('ObjVal', m.ObjVal)
    for v in m.getVars():
        print(v.VarName, v.X)
else:
